// `tool-proxy deploy apply --target <t>` — actually deploys to the
// cloud, using the config previously generated by `deploy init --target <t>`.
//
// Only `--target fly` is implemented today. It spawns Fly's CLI (`flyctl`,
// aliased as `fly`) directly to create the Fly app, set the master key,
// create the state volume, then run `fly deploy`. Each step has an
// idempotency guard so re-running is safe if a prior run was interrupted.
//
// Four steps, not five: DB-TO-FILE removed `fly postgres create` +
// `fly postgres attach`. That deleted the one step here that provisioned a
// separate billable app, the one step that was not idempotent, and the
// `<app>-db` name that a second connector in the same org would have
// collided on.
//
// Design choices:
//   - `spawn` is dependency-injected. Production callers get Node's
//     `spawnSync`; tests inject a fake. This is the ESM-native pattern —
//     `vi.spyOn(childProcess, "spawnSync")` doesn't work under native ESM
//     because module namespaces aren't configurable.
//   - Query commands (`fly apps list --json`, `fly secrets list`) capture
//     stdout so we can grep for existing resources. Mutating commands
//     (`fly apps create`, `fly deploy`) use `stdio: "inherit"` so the
//     operator sees progress live and Fly's own error messages surface
//     without buffering (avoids Bug B5 from the earlier deploy work).
//   - The Fly CLI's JSON output for `apps list` and `volumes list` uses
//     `"Name":"<value>"` — a substring check is enough to detect presence.
//     `secrets list` is text-only (no --json), so we parse line-by-line.
//   - Every remaining step IS idempotent by inspection (`apps list`,
//     `secrets list`, `volumes list` before each mutation), so there is no
//     longer a special case swallowing an expected non-zero exit. The one
//     that needed it was `fly postgres attach`; it is gone.

import { parseArgs } from "node:util";
import { spawnSync, type SpawnSyncOptions, type SpawnSyncReturns } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { randomBytes } from "node:crypto";
import { createLogger } from "../logger.js";

const log = createLogger("deploy-apply");

const USAGE = `usage: tool-proxy deploy apply --target <t>

Actually deploys to the cloud using the config from a prior \`deploy init\`.

Targets (today):
  fly     Creates the Fly app, sets the master key, creates the state
          volume, then runs \`fly deploy\`. Idempotent — skips resources
          that already exist.

Not yet implemented: fargate, aca, compose. For those, apply manually with the
cloud's native tool (aws / az / docker compose). Kubernetes has no deploy-init
target — use the Helm chart at deploy/helm/tool-proxy/.

Flags:
  --target <t>          required
  -h, --help            show this help`;

// spawnSync's type is discriminated on encoding — Buffer by default, string
// when encoding is set. We use both (Buffer for capture, inherit for tty).
// Union type keeps the DI param permissive.
export type SpawnFn = (
  command: string,
  args: readonly string[],
  options?: SpawnSyncOptions,
) => SpawnSyncReturns<Buffer> | SpawnSyncReturns<string>;

export async function runDeployApply(argv: string[]): Promise<number> {
  const { values } = parseArgs({
    args: argv,
    options: {
      target: { type: "string" },
      help: { type: "boolean", short: "h" },
    },
    allowPositionals: false,
  });

  if (values.help) {
    process.stdout.write(`${USAGE}\n`);
    return 0;
  }

  const target = values.target;
  if (!target) {
    process.stderr.write(`error: --target is required\n\n${USAGE}\n`);
    return 2;
  }

  switch (target) {
    case "fly":
      return applyFly();
    case "fargate":
    case "aca":
    case "compose":
    case "fly-mock":
      process.stderr.write(
        `error: \`deploy apply --target ${target}\` is not yet implemented.\n\n` +
        `Generate the manifests with \`tool-proxy deploy init --target ${target}\`\n` +
        `then apply with the cloud's native tool.\n`,
      );
      return 2;
    default:
      process.stderr.write(`error: unknown target "${target}"\n\n${USAGE}\n`);
      return 2;
  }
}

export function applyFly(cwd: string = process.cwd(), spawn: SpawnFn = spawnSync): number {
  // ---- Preflight ----

  // fly.toml lives under deploy/fly/ so per-platform artifacts sit in
  // the same tree as their sibling target manifests. Fly's build context
  // is the CWD (repo root) when `fly deploy` runs; we pass -c to point
  // at the nested config. This is safe because Dockerfile paths in the
  // fly.toml resolve relative to CWD, not to the fly.toml's directory.
  const flyTomlPath = resolve(cwd, "deploy/fly/fly.toml");
  if (!existsSync(flyTomlPath)) {
    log.error(
      { cwd },
      `fly.toml not found — run \`tool-proxy deploy init --target fly\` first`,
    );
    return 1;
  }

  const flyCheck = spawn("fly", ["version"], { cwd, stdio: "pipe" });
  if (flyCheck.error || flyCheck.status !== 0) {
    log.error(
      { err: flyCheck.error },
      `fly CLI not found on PATH — install flyctl: https://fly.io/docs/hands-on/install-flyctl/`,
    );
    return 1;
  }

  const flyToml = readFileSync(flyTomlPath, "utf8");
  const app = extractTomlString(flyToml, "app");
  const region = extractTomlString(flyToml, "primary_region");
  if (!app || !region) {
    log.error(
      { app, region },
      `failed to parse app / primary_region from fly.toml — regenerate with \`deploy init\``,
    );
    return 1;
  }
  log.info({ app, region }, `deploying to Fly`);

  // Ensure the connector.yaml delivered by fly.toml's [[files]] block
  // exists locally, else `fly deploy` fails on missing local_path.
  const connectorYamlDir = resolve(cwd, "deploy/fly");
  const connectorYamlPath = resolve(connectorYamlDir, "connector.yaml");
  if (!existsSync(connectorYamlPath)) {
    log.info({ path: connectorYamlPath }, `creating empty connector.yaml`);
    mkdirSync(connectorYamlDir, { recursive: true });
    writeFileSync(connectorYamlPath, "mcp_servers: []\npolicy:\n  fail_mode: fail_fast\n");
  }

  // ---- 1. Fly app ----

  if (appExists(app, spawn)) {
    log.info({ app }, `[1/4] app exists — skipping create`);
  } else {
    log.info({ app }, `[1/4] creating Fly app`);
    const r = spawn("fly", ["apps", "create", app], { cwd, stdio: "inherit" });
    if (r.status !== 0) {
      log.error({ status: r.status }, `fly apps create failed`);
      return 1;
    }
  }

  // ---- 2. Master key ----

  if (secretExists(app, "CONNECTOR_KEY_B64", spawn)) {
    log.info({ app }, `[2/4] CONNECTOR_KEY_B64 already set — skipping mint`);
  } else {
    log.info({ app }, `[2/4] minting master key + setting CONNECTOR_KEY_B64`);
    const key = randomBytes(32).toString("base64");
    const r = spawn(
      "fly",
      ["secrets", "set", `CONNECTOR_KEY_B64=${key}`, "--app", app],
      { cwd, stdio: "inherit" },
    );
    if (r.status !== 0) {
      log.error({ status: r.status }, `fly secrets set failed`);
      return 1;
    }
  }

  // ---- 3. State volume ----

  if (volumeExists(app, "state", spawn)) {
    log.info({ app }, `[3/4] state volume exists — skipping create`);
  } else {
    log.info({ app, region }, `[3/4] creating state volume`);
    const r = spawn(
      "fly",
      [
        "volumes", "create", "state",
        "--size", "1",
        "--region", region,
        "--app", app,
        "--yes",
      ],
      { cwd, stdio: "inherit" },
    );
    if (r.status !== 0) {
      log.error({ status: r.status }, `fly volumes create failed`);
      return 1;
    }
  }

  // ---- 4. Deploy ----

  log.info({ app }, `[4/4] running fly deploy (foreground)`);
  // Build context is CWD (repo root). The fly.toml's [build] dockerfile
  // path is resolved by fly relative to the fly.toml directory
  // (deploy/fly/), so that file uses "../../connector/Dockerfile" to point
  // back into the repo tree. Don't try to override with --dockerfile here;
  // fly ignores the flag when [build] is set.
  const deployResult = spawn(
    "fly",
    ["deploy", "-c", "deploy/fly/fly.toml"],
    { cwd, stdio: "inherit" },
  );
  if (deployResult.status !== 0) {
    log.error({ status: deployResult.status }, `fly deploy failed`);
    return deployResult.status ?? 1;
  }

  log.info({ app }, `deploy complete`);
  printPostDeployNextSteps(app);
  return 0;
}

// Explicit post-deploy summary — written directly to stdout so it bypasses
// the pino formatter and lands as an unmissable block after the log
// output. Deliberately verbose because operators (a) reach for `fly proxy`
// and get an unexplained 403 — the Inspector is loopback-only and fly proxy
// arrives from the mesh address — and (b) forget the HSTS-upgrade trap. The
// relay/proxy pair that fixes it now lives in scripts/fly-inspector.sh, which
// also owns teardown, so this block points at the script rather than teaching
// the recipe inline.
function printPostDeployNextSteps(app: string): void {
  const block = `
==============================================================
  Deploy complete — ${app}
==============================================================

Next steps:

  1. Confirm no public IP (outbound-only invariant):

       fly ips list -a ${app}

     MUST return empty. If it lists an IPv4/IPv6, release with
     \`fly ips release <address> -a ${app}\` before proceeding.

  2. Open the Inspector — one command, from a checkout of this repo:

       ./scripts/fly-inspector.sh ${app}

     It prints a URL and tears everything down on Ctrl-C.

     Why a script and not just \`fly proxy\`: the Inspector is loopback-only,
     and \`fly proxy\` arrives from the Machine's fdaa: mesh address, so it
     gets 403 {"ok":false,"error":"forbidden: loopback only"} on every
     dashboard route. The script supplies the missing loopback hop. Adding
     API clients in the Network Access panel does NOT help — those are
     credentials for scripts calling /oauth/token, not for a browser.

  3. Open the URL it prints.

     Use \`http://\` explicitly. Chrome HSTS on localhost can force
     https:// which the inspector doesn't serve (ERR_CONNECTION_RESET).

  4. In the browser, fill in the "Configure Tunnel" modal:

       Controller URL:  https://<your-controller>
       Connector Name:  must match the Tunnel Security row Name
                        on your controller (case-sensitive)
       Auth posture:    static bearer OR OAuth2 (match the row type)

     Save. The status pill goes:
       closed  →  connecting  →  open  (green)

  5. Verify tools flowing (once tunnel is open):

       fly logs -a ${app}   # look for "tunnel opened" + "register-ack"

==============================================================

`;
  process.stdout.write(block);
}

// ---- helpers ----

function appExists(name: string, spawn: SpawnFn): boolean {
  const r = spawn("fly", ["apps", "list", "--json"], { stdio: "pipe" });
  if (r.status !== 0) return false;
  const json = bufferToString(r.stdout);
  // Fly's JSON output is pretty-printed with a space after the colon
  // (`"Name": "tool-proxy"`), so a bare `"Name":"..."` substring check
  // misses. Regex is whitespace-tolerant and escapes the name for regex
  // metacharacters (Fly app names are hyphen-safe but be defensive).
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`"Name"\\s*:\\s*"${escaped}"`).test(json);
}

function secretExists(app: string, key: string, spawn: SpawnFn): boolean {
  const r = spawn("fly", ["secrets", "list", "--app", app], { stdio: "pipe" });
  if (r.status !== 0) return false;
  const text = bufferToString(r.stdout);
  // `fly secrets list` output: header row + one row per secret. Each row
  // starts with the secret name (followed by whitespace and metadata).
  return text.split("\n").some((line) => line.trim().startsWith(key));
}

function volumeExists(app: string, name: string, spawn: SpawnFn): boolean {
  const r = spawn("fly", ["volumes", "list", "--app", app, "--json"], { stdio: "pipe" });
  if (r.status !== 0) return false;
  const json = bufferToString(r.stdout);
  return json.includes(`"Name":"${name}"`);
}

// Parse `key = "value"` or `key = 'value'` from TOML. We control the fly.toml
// template so we know it's a simple line-based assignment (no interpolation,
// no arrays). A full TOML parser would be overkill.
function extractTomlString(toml: string, key: string): string | undefined {
  const match = toml.match(new RegExp(`^${key}\\s*=\\s*['"]([^'"]+)['"]`, "m"));
  return match?.[1];
}

// spawnSync returns Buffer | string depending on encoding. Normalize.
function bufferToString(v: Buffer | string | null | undefined): string {
  if (v === null || v === undefined) return "";
  return typeof v === "string" ? v : v.toString("utf8");
}
